/** Currencies that have NO minor unit (yen etc.) — displayed without decimals. */
export const ZERO_DECIMAL_CURRENCIES = new Set([
  "JPY", "VND", "IDR",
  "KRW", "CLP", "ISK", "HUF", "PYG", "UGX", "TZS", "KHR", "LAK", "MMK",
  "XOF", "XAF", "RWF", "VUV", "KMF", "DJF", "GNF", "XPF",
]);

input.command:
cd /opt/nxeon && cat > /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/chk.mjs <<'EOF'
import { CURRENCIES, DEFAULT_CURRENCY_RATES, ZERO_DECIMAL_CURRENCIES } from '/opt/nxeon/lib/currency.ts';
import { COUNTRY_TO_CURRENCY } from '/opt/nxeon/lib/geo-currency.ts';

const curKeys = Object.keys(CURRENCIES);
const rateKeys = Object.keys(DEFAULT_CURRENCY_RATES);
let problems = [];

// Every CURRENCIES key must have a rate
for (const k of curKeys) if (!(k in DEFAULT_CURRENCY_RATES)) problems.push(`CURRENCIES ${k} has no rate`);
// Every rate must have a currency meta (optional but nice)
for (const k of rateKeys) if (!(k in CURRENCIES)) problems.push(`RATE ${k} has no CURRENCIES entry`);
// Every COUNTRY_TO_CURRENCY value must exist in both CURRENCIES and rates
const cc = Object.entries(COUNTRY_TO_CURRENCY);
for (const [country, cur] of cc) {
  if (!(cur in CURRENCIES)) problems.push(`COUNTRY ${country}->${cur} missing in CURRENCIES`);
  if (!(cur in DEFAULT_CURRENCY_RATES)) problems.push(`COUNTRY ${country}->${cur} missing in RATES`);
}
// Zero-decimal codes must exist in CURRENCIES
for (const k of ZERO_DECIMAL_CURRENCIES) if (!(k in CURRENCIES)) problems.push(`ZERO_DECIMAL ${k} missing in CURRENCIES`);

const uniqCur = new Set(cc.map(([,v])=>v));
console.log('CURRENCIES:', curKeys.length);
console.log('RATES:', rateKeys.length);
console.log('COUNTRIES mapped:', cc.length);
console.log('distinct currencies used by countries:', uniqCur.size);
console.log('ZERO_DECIMAL count:', ZERO_DECIMAL_CURRENCIES.size);
console.log(problems.length ? 'PROBLEMS:\n'+problems.join('\n') : 'CONSISTENCY: ALL OK');
EOF
npx tsx /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/chk.mjs 2>&1 | tail -20
